    otoraComment: "SpaceXは「4回目が最後」の状況で成功した会社だ。Falcon 1は2006年3月、2007年3月、2008年8月と3回続けて失敗し、Musk本人も後に、4回目がうまくいかなければSpaceXは終わっていたと振り返っている。同じ2008年はTeslaの資金繰りも重なり、本人が「最悪の年」と呼んだ年でもある。普通の起業家なら3回目で撤退していただろう。それでも9月28日に軌道へ届き、3か月後の12月23日にはNASAから約16億ドルの補給契約を取った。2004年にシャトル退役が決まり、NASAが民間に輸送を任せ始めた転換期に間に合ったのは、失敗しても打ち上げをやめなかったからだ。再使用という、業界の誰もが不可能だと見た仮説に賭け続けた胆力は異常と言っていい。あなたなら3回目の失敗のあと、4回目を打ち上げると決められただろうか。",
