    situation: "1837年10月31日、オハイオ州シンシナティで、ともに移民のろうそく職人William Procterと石鹸職人James Gambleが共同事業を始めた。2人の義父Alexander Norrisが、同じ獣脂などを原料に使う仕事だとして組むよう勧めた。払込資本は約7,192ドル。1850年代末には従業員約80人・売上100万ドル超に育ち、南北戦争では北軍に石鹸とろうそくを納めた。1879年に石鹸Ivoryを発売し、1890年に株式会社化。1931年にはNeil McElroyがブランド別の担当制を提案した。",
