    otoraComment: "P&Gの天才的な発明は1931年の「ブランドマネジメント制度」だ。Neil McElroyが提案した、ブランドごとに責任者を置く仕組みで、同じ会社の中で製品同士を競わせる。官僚化しやすい大企業の内側に市場原理を持ち込んだと言える。出発点は1837年、ろうそく職人Procterと石鹸職人Gambleの補完的な組み合わせだった。1860年には開戦直前に原料のロジンを買い込み、南北戦争では北軍に石鹸とろうそくを納めて全国に名を知られた。1879年のIvory、1882年の年1.1万ドルの広告予算と商標登録で、名前をつけて売る消費財ブランドの型をつくった。189年続いた秘訣は「自分たちで自分たちを揺さぶり続ける」ことだろう。あなたの会社では、いったい誰が今の主力商品に挑んでいるだろうか。",
