    flag: "🇯🇵",
    axes: { society: 3, customer: 4, self: 3 },
    axesScore: 36,
    insight: "消費者起点の哲学。1973年に日本へ参入したP&Gとの約50年の競争が進化を促進",
    insightEn: "A consumer-first philosophy. Some 50 years of rivalry with P&G, which entered Japan in 1973, forced its evolution.",
    situation: "1887年、長瀬富郎（1863〜1911）が東京・日本橋馬喰町で洋小間物商「長瀬商店」を開いた。輸入品を扱うなかで石鹸の製造に乗り出し、外国製に並ぶ品質の石鹸づくりに成功する。1890年10月、桐箱入りの高級化粧石鹸「花王石鹸」を発売。同時に大阪へ代理店を置き、新聞広告を使って最初から全国を商圏に据えた。1902年には原料の仕込みから包装まで一貫して行う直営の請地工場が完成。社名は花王石鹸などを経て、1985年に花王となった。",
    situationEn: "Tomiro Nagase pivoted from importing miscellaneous goods to making high-quality Japanese soap. Launched 'Kao Soap' in 1890 at 7 sen per bar. Built national distribution through newspaper ads and posters featuring famous geisha.",
