      solution: "外国製に並ぶ品質の国産石鹸を桐箱入りで出した。1931年には品質を上げ、手に入りやすい価格で新装発売",
      team: "長瀬富郎は発売と同時に大阪へ代理店を置き、新聞広告を打った。日本のマーケティングの先駆者",
