    otoraComment: "金剛組の1,448年は「専門特化が最長の生存戦略」の究極の証明だ。578年、聖徳太子が百済から招いた工匠の一人、金剛重光が四天王寺を建て、以後40代にわたり社寺建築を担った。四天王寺は1576年の石山合戦、1614年の大坂冬の陣で焼け、1934年には室戸台風で五重塔が倒れた。そのたびに金剛組が建て直した。1932年に37代が困窮の末に自ら命を絶っても、妻が初の女棟梁として継いだ。それほどの危機を本業でしのいだ会社が、1980年代のバブル期に借入で不動産へ投資し、崩壊後に過剰債務へ陥る。2006年、髙松建設が設けた新会社に事業を譲り、技術と宮大工ごと引き継がれた。「専門外への拡大が唯一の死因」は、全ての老舗への警告として読める。",
    otoraCommentEn: "Kongō Gumi's 1,448 years is the ultimate proof that 'specialization is the longest survival strategy.' The temple carpenter invited by Prince Shōtoku in 578 built Shitennōji, and for 40 generations they did nothing but temples and shrines. They transmitted the craft so faithfully that a three-meter scroll from the 17th century still survives. Their only failure was expanding into real estate in the 1990s, which led to becoming a subsidiary of Takamatsu Construction in 2006. 'Expansion outside the specialty is the only real cause of death' is a warning to every long-lived company.",
