    survivalKey: "ヴェネツィア共和国の「職人をムラノに集めた」政策の中で生き残り、クリスタッロ発明でトップの地位を取り、以降700年その地位を譲らなかった。地理（ムラノ島）＋技法（クリスタッロ）＋家族（24代）の三重ロックが、他社が決して到達できない壁を築いている。",
    survivalKeyEn: "Barovier survived the Venetian Republic's policy of confining glassmakers to Murano, took the lead by inventing cristallo, and has not given up that lead for 700 years since. A triple lock — geography (Murano), technique (cristallo), and family (24 generations) — builds a wall no competitor can reach.",
    otoraComment: "バロヴィエル＆トソの731年は「島と家族と技術の三重ロック」。ムラノ島に閉じ込められた1295年、むしろそれが参入障壁に変わった。1400年代にクリスタッロ（透明ガラス）を発明した瞬間、ヴェネツィアングラスの代名詞になった。24代の同族継承は血縁より「技術を継ぐ意志」の継承。工業化を拒否し、手作りと高単価に振り切ったことで、IKEAや中国ガラスと別の市場で生きている。「競争しない」選択が700年の秘訣。",
    otoraCommentEn: "Barovier & Toso's 731 years come from a triple lock — island, family, craft. When the Venetian Republic confined glassmakers to Murano in 1295, that constraint turned into a moat. The moment Angelo invented cristallo in the 1400s, they became the face of Venetian glass. Their 24-generation succession isn't really about bloodline; it's about the transmitted will to continue the craft. By refusing industrialization and going all-in on handmade, high-margin work, they live in a market that IKEA and Chinese glass simply don't reach. 'Not competing' is the secret of 700 years.",
