    otoraComment: "アンティノーリの641年で最も興味深いのは1971年のティニャネロ事件。当時、イタリアのワインはDOC（法定格付け）に縛られ、決められたブドウ品種を決められた比率で使うことが「貴族ワイナリーの誇り」だった。ピエロ・アンティノーリはそれを捨て、「テーブルワイン」としてリリースし、のちにボルドー品種（カベルネ・ソーヴィニヨン）も混ぜた。業界中から叩かれたが、10年後には世界の高級レストランでボルドー1級と並び、「スーパートスカーナ」という新カテゴリを生んだ。26代の積み重ねが「伝統を壊す勇気」を生んだ。守るために壊せる家族が641年を作る。",
