    survivalKey: "「永平寺の水・福井の米・8代の家系・雪室の地理」という4重の地理的ロック。さらに7代目が1975年に「大吟醸の芸術化」という時代転換を起こしたことで、縮小する日本酒市場の中で独自ポジションを確保。伝統を守りながら、一点だけ時代を先取る戦略が222年を作っている。",
