    insightEn: "The pinnacle of Scotch. Single-malt king — a bottle once sold at auction for $2.7M.",
    situation: "1824年、アレクサンダー・リードがスコットランド・スペイサイドで蒸留免許を取得し創業。シェリーカスク熟成を200年貫き、シングルモルトの「頂点」の地位を築いた。1926年蒸留のボトルが2023年に$2.7M（約4億円）でサザビーズで落札され、ウイスキー史上最高額を更新。1996年にハイランド・ディスティラーズの傘下に入り、1999年にその親会社ごとエドリントン・グループ（スコットランドの老舗グループ）とウィリアム・グラントに買収されたが、ブランド・製法・地理は完全継承。60年熟成ボトルや希少ビンテージは富裕層のコレクターズアイテム化し、金融商品としても流通する。",
    situationEn: "Founded in 1824 when Alexander Reid obtained a distilling license in Speyside, Scotland. For 200 years, Macallan has stood by sherry-cask maturation, cementing its position as the pinnacle of single-malt whisky. A bottle distilled in 1926 sold at Sotheby's in 2023 for $2.7M, setting the all-time auction record for whisky. Came under Highland Distillers in 1996, which the Edrington Group (a historic Scottish holding) and William Grant acquired in 1999, but brand, process, and geography were preserved intact. 60-year vintages and rare editions have become collectors' items among the wealthy — and increasingly trade as financial assets.",
