      traction: "$2.7M auction record. A constant top-3 distillery worldwide.",
      moat: "Speyside geography + secured sherry casks + 200yr reputation. Triple lock.",
      revenue: "Ultra-high unit price on rare vintages. Two-tier model: standard line + limited releases.",
      financial: "Financially stable under Edrington. Inventory = spirit aging in casks = an appreciating asset.",
      efficiency: "Maturation takes 10–60 years. Scarcity is born by abandoning efficiency.",
      exit: "Acquired by Edrington, not family-owned — but brand independence is preserved.",
      timing: "Entered the single-malt wave early and exploded as Asian wealth rose.",
      insight: "'Assets brewed by time.' The insight that turned whisky into an investment class.",
