    situationEn: "Mark Zuckerberg launched thefacebook.com on February 4, 2004 from his Harvard dorm (Kirkland House H33). Co-founders: Eduardo Saverin (CFO, initial $1,000), Dustin Moskovitz, Chris Hughes, and Andrew McCollum. Zuckerberg had been disciplined the previous fall over Facemash, and from that experience pivoted to a 'consent-based real-name' model. Within 24 hours of launch, 1,200 students signed up; within a month, more than half of Harvard's undergraduates. The site expanded to Yale, Columbia, and Stanford in March, reaching 30 schools by May. Until Peter Thiel's $500K investment in August, the company ran almost entirely on Saverin's funding.",
