    otoraComment: "2004年5月のFacebookはNCG35点、Harvard寮で5人がサーバ月$85で30大学を運営する草創期。Zuckerbergの異常さは、Facemashで懲戒処分を食らった反省から「合意した実名制」へ転換できたこと。MySpaceが匿名で爆伸びしている最中に「閉じることで価値が出る」と逆張りしたInsight=5が全て。Saverin $1,000+自己資金+Thielの出資$500K（8月）でバーンレートは極小、5人で30大学にスケールするバーンマルチプルは異常値。NCG法則「Insight 5+Timing 5なら存続可」のうち両方MAXを取った稀有な例。30億人到達は20年後、ここではまだネットワーク効果はFutureのみ、moatはほぼゼロ。",
    otoraCommentEn: "Facebook in May 2004 scored NCG 35 — a five-person company running 30 universities from a Harvard dorm on $85/month in servers. What's unusual about Zuckerberg is that he learned from Facemash's disciplinary fallout and pivoted to 'consent-based real names.' While MySpace was exploding on anonymity, only he articulated the contrarian 'closing the network creates value' — Insight=5, that's everything. With Saverin's $1,000 plus self-funding and Thiel's $500K investment in August, burn was minimal, and a five-person team scaling to 30 schools is an off-the-charts burn multiple. A rare case where both halves of the NCG rule 'Insight 5 + Timing 5 keeps you alive' hit max simultaneously. The 3 billion-user destination was 20 years away — here, network effects existed only as future, and moat was essentially zero.",
