    survivalKeyEn: "What an insurer sells is nothing but a promise — the product itself is made of trust. The simple fact of having honored the promise for 147 years is the moat, and it cannot be manufactured in the short term with capital or technology. In a rare industry where time and track record are the product, only those who kept winning from the start remain.",
    otoraComment: "東京海上の創業は「船が沈むたびに船主や荷主が破産する構造を変えた」こと。1879年、渋沢栄一が主唱し、岩崎弥太郎や旧藩主らが出資して日本初の保険会社が営業を始めた。元手は旧藩主が受け取った金禄公債で、鉄道に向かうはずだった資金を渋沢が海上保険に向けさせた。最初の商品は貨物海上保険。積荷のリスクを保険料として全体でプールする仕組みは、近代商業の基本インフラになった。147年後、2004年の日動火災との合併、2008年以降の米英での買収を経て、2026年3月にはバークシャー・ハサウェイと提携するまでになった。一方で2023年には保険料の事前調整で行政処分も受けた。保険会社が信用商売である限り、積み上げた実績は最強のmoatであり、最も壊れやすい資産でもある。",
    otoraCommentEn: "Tokio Marine was founded to 'change the structure where every sinking ship bankrupts its owner.' In 1879, the two giants of the Meiji business world — Shibusawa and Iwasaki — were its founding promoters. Pooling trading-vessel risk through premiums is a fundamental infrastructure of modern commerce. 147 years later, it's Japan's #1 non-life insurer with operations in 46 countries. So long as insurance is a trust business, 100 years of track record is itself the strongest moat. Importing and implementing the concept of 'risk diversification' in Japan is a feat that belongs in the canon of financial history.",
