    otoraComment: "東京ガスの本質は「エネルギーの姿は変わっても導管網は残る」こと。1885年、渋沢栄一らが東京府の瓦斯局を24万円で払い受けたとき、需要家はわずか343戸、用途はガス灯だった。そこから調理・暖房へ広げ、1902年には炊飯竈でガス器具として日本初の特許を取り、1967年にはLNGの輸入契約を結んで中身を入れ替えた。いま試しているのは合成メタン。中身は何度も変わったが「パイプ」は消えない。2026年3月期のガス本支管は総延長6万7,287km、取付メーターは約1,269万件。141年かけて地下に埋めた資産が、次の脱炭素時代にも活きる可能性がある。インフラ企業の強みは「時間で作った物理資産」。新興エネルギー企業がどれだけ優秀でも、首都圏の地下にこれを作り直すのは不可能に近い。",
    otoraCommentEn: "Tokyo Gas's essence: 'energy's face changes, but the pipe network remains.' From gas lamps in 1885 through cooking, heating, city gas, LNG, and now hydrogen — the contents have changed five times, but the pipes never disappear. Underground assets accumulated across 141 years may carry into the next 100-year hydrogen era. The strength of a utility is 'physical assets built by time.' No matter how capable a new energy player is, rebuilding pipes under the greater Tokyo area for 11.5 million connections is nearly impossible.",
