    survivalKey: "黒船に対抗する造船所として生まれた国家的危機感が、173年分のイグニッションになり続けている。造船→重工→航空エンジン→ロケットと売り物は変わっても、「日本が独立するために自国で作る」という創業動機が新しい高難度領域に乗り移り続けた。",
