    otoraComment: "IHIの原点「石川島造船所」は1853年、ペリー来航の年に生まれた。幕府が水戸藩に命じて造らせた造船所で、「黒船に対抗できる船を自分たちで作れなければ独立できない」という危機意識が出発点。1876年に平野富二が跡地を借りて民営化し、1889年に会社組織に、1893年には渋沢栄一が会長に就いた。1924年には飛行機製作所を設け、1960年の播磨造船所との合併では土光敏夫が初代社長に立った。173年後、航空エンジンとロケットを作っている。ただ2024年3月期には、約15%を持つPW1100Gエンジンの不具合で過去最大の最終赤字を出し、翌期に純利益1,127億円まで戻した。江戸の藩営事業が明治の民営化を経て、令和の宇宙産業に繋がっている。危機感から始まった事業が長く生き残るのは、スタートエネルギーが本物だからか、危機のたびに乗り換える力が身についたからか。",
    otoraCommentEn: "IHI's origin — Ishikawajima Shipyard — was founded in 1853, the year of Perry's Black Ships, by the Mito lord. The driving force was a sense of crisis: 'if we can't build ships that can stand up to the Black Ships ourselves, we are not independent.' It was privatized by Tomiji Hirano in 1876 and incorporated in 1889 with Shibusawa among the investors. 173 years later, it makes aircraft engines and rockets. An Edo-era clan enterprise, through Meiji privatization, connects to Reiwa's space industry. Businesses born from genuine urgency survive long because the ignition energy is real.",
