    survivalKeyEn: "A one-sentence managerial constitution — 'don't chase passing profits, honor trust, respond to the times' — has operated as the decision standard for generations of banto managers across 436 years. Splitting ownership from management, with the family owning and the banto running the business, erases generational risk and lets them steer in a single direction for centuries on a single house code.",
    otoraComment: "住友436年の核は「営業の要旨」という経営憲法。初代・住友政友が残した『文殊院旨意書』の精神を、1882年に総理事の広瀬宰平が「住友家法」として成文化し、1891年には「信用を重んじ確実を旨とする」「浮利に趨り軽進すべからず」の2カ条を家法の冒頭に掲げた。同じ年に家法と家憲を分け、所有と経営の分離をはっきりさせている。別子銅山という1つの鉱山を282年経営し、煙害には伊庭貞剛が製錬所の四阪島移転で応え、その周りに化学や林業が育った。同族家が所有し、経営は総理事に任せる構造が、世代リスクを抑えてきた。旨意書から数えれば約400年、創業期の言葉が判断を統一してきたことになる。経営理念の力はどこまで及ぶのか、考えさせられる。",
    otoraCommentEn: "Sumitomo's 436-year core is the managerial constitution called 'Business Principles.' Codified in 1891 from the spirit of founder Masatomo's precepts, 'honor trust, don't chase passing profits' — that document has functioned for 400 years as the decision standard for the banto managers. They ran a single mine, Besshi copper, for 282 years, and expanded into chemicals, metals, and trading before it ran out. A structure where the family owns but delegates management to banto erases generational risk. A single passage written by a founder can unify decisions for hundreds of years — the real power of management philosophy.",
