    otoraComment: "日本郵船の本質は「景気循環を141年生き延びた」こと。そもそもの出発点からして、郵便汽船三菱と共同運輸の運賃競争が共倒れ寸前になり、1885年に政府が仲介して合併させた会社だった。海運は典型的な市況産業で、好況と不況を繰り返す。終戦時には所有船が37隻まで減ったが、1968年に日本初のフルコンテナ船「箱根丸」を就航させ、2017年には川崎汽船・商船三井とコンテナ船事業をONEに統合した。そのONEの好調もあって、2023年3月期には経常利益1兆1,098億円を記録している。三菱から受け継いだ船隊と航路が、次の世代の経営陣を乗せて航海を続ける。「循環産業で生き残る」のは、好況時に蓄え不況時に守る規律の積み重ねだろう。次の波で、その規律がまた試される。",
