    otoraComment: "FTXの教訓は、「効果的利他主義」の衣を着た最大級の詐欺だったこと。SBFは「稼いで寄付する」を掲げ、2022年の中間選挙では民主党側に約$3,980万を献金し、マイアミのアリーナ命名権やスーパーボウル広告で「善良で堅実な取引所」の顔を作った。その裏で顧客資産はAlameda Researchへ流れ、破綻時には顧客の約$80億が失われていた。後任CEOのJohn Ray IIIはEnronの清算を手がけた人物だが、これほど完全な統制の失敗は見たことがないと述べた。会計はQuickBooks、記録はほぼなく、本社はバハマ。評価額$320億に出資した投資家も、2021年の熱狂のなかで懐疑を手放していた。ブランドが道徳的に立派すぎる時ほど、中を見ろ——禁錮25年の判決が市場に残したのは、その警告ではないだろうか。",
