    failReasonEn: "The lethal element was that three layers of authority — DAX30, auditor EY, and the regulator BaFin — had all stamped 'blue-chip' on the company. The thicker the external legitimacy, the looser the internal verification — which is how $2B of phantom revenue ran untouched for over a decade. Authority kills doubt.",
    otoraComment: "WirecardはDAXに入る「ドイツの誇り」だった。2018年には時価総額が€240億に達し、老舗のCommerzbankに代わって指数に入った。疑いの声は早くからあった。FTのDan McCrumは2015年から事業モデルを問い、2019年にはアジアでの帳簿操作を報じた。だが当局BaFinは空売りを禁止し、ミュンヘンの検察は記者の方を捜査した。最後は監査法人EYが信託口座の€19億（約$21億）を確認できず、名指しされたフィリピンの銀行2行が書類は偽造だと答えて終わった。CEOは逮捕、COOは逃亡中。「優良企業」という社会的ラベルが、いちばん分厚い目隠しになる。数字が綺麗すぎる時、権威ある監査や当局がついている時ほど、誰が実物を確かめたのかを問うべきではないか。",
