    failReasonEn: "They didn't solve a customer's pain; they solved the founder's technology aesthetic. The moment 'you can squeeze the packet by hand' was exposed, the $400 price and $120M of funding evaporated together with the product's reason to exist. The inevitable consequence of an insight score of 1.",
    otoraComment: "Juiceroの死因は、問題が存在しない市場に約$1.2億を投じたこと。Wi-Fiでつながり、約8,000ポンドの力で専用パックを搾る$699のプレス機。パックは1つ$5〜7で、日持ちは約8日。2017年4月、Bloombergの記者がパックを手で絞ってもほぼ同じ結果になると示した瞬間、機械の存在理由が消えた。GVもKleiner Perkinsも出資していたのに、誰も手で絞ってみなかった。翌日には全額返金を申し出たが、9月に販売を停止し、12月に会社は消えた。シリコンバレーが「テクノロジー＝価値」と錯覚した時代の象徴だ。製品を顧客の手で試す、それだけで防げたのではないか。",
    otoraCommentEn: "Juicero died from 'putting $120M into a market where the problem doesn't exist.' A $400 Wi-Fi-enabled juicer plus $5–8 proprietary packets. A single sentence from a Bloomberg reporter — 'you get the same juice if you squeeze the packet by hand' — erased all of the value. Google Ventures and Kleiner Perkins were invested, and yet no one had squeezed the packet by hand. A symbol of the Silicon Valley era that confused 'technology' with 'value.' A simple customer-side product test could have prevented it.",
