    otoraComment: "Pets.comの死因は「売るほど赤字」という構造。1袋$22のペットフードに$20の送料が乗る。値下げ競争するほど赤字が膨らむモデルを、誰も止めなかった。スーパーボウル広告+靴下人形マスコットで認知は取れたが、買い物は近所のスーパーで十分だった。IPOで調達した$82.5Mを含む資金を9ヶ月で燃やし尽くして清算。ドットコムバブルの象徴になった。ユニットエコノミクス（1件売った時の利益）が破綻している事業は、規模拡大が破綻を加速する。",
    otoraCommentEn: "Pets.com died from the structure 'the more you sell, the more you lose.' $22 pet food carried $20 of shipping. No one stopped the model that bled more with every round of price cutting. Super Bowl ads and a sock-puppet mascot won awareness, but the local supermarket was plenty. Burned through its funding, including the $82.5M IPO raise, in nine months and liquidated. Became the symbol of the dot-com bubble. When unit economics are broken — when a single sale loses money — scaling only speeds the collapse.",
