    situation: "1911年6月、実業家Charles Flintが4社を合併させ、ニューヨーク州でComputing-Tabulating-Recording Company（CTR）が生まれた。従業員は約1,300人で、パンチカード式の集計機などを扱った。1914年にThomas J. Watson Sr.が加わって翌年社長となり、1924年に社名をIBMに改めた。その後、1964年のSystem/360、1981年のIBM PCで業界の標準をつくり、2005年にはPC事業をLenovoへ売却。今はRed Hatを軸にソフトとAIへ重心を移している。",
    situationEn: "Founded as the Computing-Tabulating-Recording Company. Punch cards → mainframes → PCs → IT services → AI: pivoted every time the technology wave changed. Showed the resolve to sell off the PC business to Lenovo even after setting the PC industry standard.",
