    survivalKeyEn: "They sold the PC business whose industry standard they themselves had set to Lenovo the moment they saw the peak pass. Building a structure that consistently produces executives willing to burn the company's success playbook is what made five reinventions over 115 years possible. In an industry where legacy firms die unable to abandon their founding business, IBM does so without hesitation.",
    otoraComment: "IBMの115年は「事業を捨てる勇気」の歴史。パンチカード、メインフレーム、PC、ITサービス、そしてAI。1993年には当時の米企業史上最大となる$80億の赤字を出し、外部から来たGerstnerが立て直した。2002年にPwCのコンサル部門を買い、2004年12月にはPCの業界標準を作った張本人がPC事業を約$17.5億でLenovoへ売った。Romettyの時代には5年以上の減収に耐えながら資産を入れ替え、2019年には$340億でRed Hatを買った。自分の成功体験を燃やせる経営者が何人もいたことが、この会社の強さだろう。顧客の信頼は「技術」より「IBMを選んでクビにはならない」という安心感から来ている。官僚化との終わりなき戦いは、今も続いている。",
    otoraCommentEn: "IBM's 115 years is the history of 'the courage to abandon businesses.' Punch cards → mainframes → PCs → IT services → AI. The biggest call was that a company that set the PC standard sold the PC business to Lenovo. They had multiple CEOs (Gerstner, Rometty) willing to burn their own success playbook. 95% of the Fortune 500 as customers — that trust isn't about 'technology,' it's about the safety of 'nobody got fired for choosing IBM.' The endless fight against bureaucratization continues.",
