    virtue: "ヘクシス（習慣的卓越性）",
    virtueEn: "Hexis (habituated excellence)",
    survivalKey: "失敗作を捨てずに横展開する文化を制度化した。「くっつかない糊」という失敗がポストイットに化けた事例を、15%ルールという仕組みで再現可能にしている。結果として13万件の特許と6万製品の分散が生まれ、1品種の不振が会社を揺らさないポートフォリオになった。",
    survivalKeyEn: "They institutionalized a culture of never discarding failures but repurposing them horizontally. The '15% rule' makes the Post-it story — an adhesive that wouldn't stick turned into a product — reproducible. The result is 130,000 patents spread across 60,000 products, a portfolio where the weakness of any one item cannot shake the company.",
    otoraComment: "3Mの核は「失敗を活かす文化」。創業の鉱山は掘ってみたら価値のない石で、そこから研磨材の会社に転じた。McKnightに研究をやめて本業に戻れと言われたRichard Drewは、1925年にマスキングテープを完成させ、McKnightはそこから研究者を縛らない大切さを学んだと伝えられる。勤務時間の15%を自分のテーマに使える制度もその延長にある。ポストイットは1968年の「くっつかない糊」という失敗作を、1974年に同僚Art Fryが賛美歌集のしおりに使ったことから始まった。捨てずに横へ流した判断が、看板商品を作ったのだ。2014年に累計10万件を超えた特許と約6万種の製品は、素材技術を水平展開し、1つが他を支える構造の結果だろう。遠回りに見える多角化が、実は近道だったのかもしれない。",
    otoraCommentEn: "3M's core is 'a culture that makes use of failures.' The Post-it was born from an adhesive that wouldn't stick — a failed product — and an employee's choice not to throw it out but to repurpose it horizontally created a $1B/year business. It was exactly because the original mining business failed that they could pivot to sandpaper. The 15% rule — employees can use 15% of work time on self-directed research — produced 130,000 patents and 60,000 products. Diversification looks like a detour, but horizontally extending materials technology creates a structure where each part supports the others.",
