    otoraComment: "フィリップスの教訓は「135年企業が自分を捨てられるか」という問い。電球で始まり、カセットテープやCDで20世紀の家電を引っ張った会社が、2006年に半導体を、2012年にテレビを、2016年に創業事業の照明を、2021年に家電を手放した。医療への全振りは、1910年代に研究所でX線管を手がけた源流へ戻る選択でもあった。道は平坦ではない。2021年6月の呼吸器リコールは世界で約1,500万台に及び、2024年4月には米国で販売を縛る同意判決を受け、同年は純損失€6.98億だった。普通の老舗企業は創業事業を捨てる判断ができない。彼らは自分の歴史より未来を選んだ。「何屋か」を変える勇気は、「何屋か」を守る勇気より100倍難しい。生存戦略としては正解だった——その覚悟の値段を、リコールが教えている。",
