      market: "プレミアムシャンパン市場。祝賀需要で不況でも縮みにくい",
      problem: "「祝う」という人類共通の儀式に対する商品提供",
      solution: "ブドウ栽培+熟成+ブランドストーリーの一体化",
      team: "モエ家→LVMHへの事業継承。アルノー家の経営力と組み合わせ",
