      team: "Business succession from the Moët family to LVMH. Combined with the Arnault family's operating capability.",
      traction: "Over 30M bottles a year, sold in 150+ countries.",
      moat: "Own Champagne vineyards + 283-year brand + imperial endorsement.",
      revenue: "Premium price × volume. A sweet spot at $50–200 a bottle.",
      financial: "One of the major pillars of LVMH's consolidated financials. Highly profitable.",
      efficiency: "Vineyard time cannot be compressed. That itself is differentiation.",
      exit: "Integrated into LVMH in 1987. Listing via LVMH itself.",
