    virtue: "ヘクシス（習慣的卓越性）",
    virtueEn: "Hexis (habituated excellence)",
    tierLabelEn: "283 years",
    survivalKey: "「ナポレオンが飲んだ」という歴史そのものが、味以上の価値を283年売り続けている。高級品の世界では誰が飲んだかが味を凌駕し、皇帝の記憶というmoatは競合が逆立ちしても複製できない。時間と物語でしか作れない堀を持つと、不況でも単価が下がらない。",
    survivalKeyEn: "The history itself — 'Napoleon drank this' — has been selling for 283 years at a price above taste. In luxury, who drank it overwhelms what it tastes like, and a moat made of an emperor's memory cannot be replicated by any competitor, no matter what they do. When your moat is built only from time and story, prices don't drop even in recessions.",
    otoraComment: "モエの強さは「ナポレオンに愛された」という歴史そのもの。クロード・モエは1743年創業、ナポレオンがエペルネに立ち寄るたびに樽でシャンパンを買い、戦場にも持っていった。皇帝のお墨付きが283年効いてる。味が同じでも「これをナポレオンも飲んだ」が単価を倍にする。1987年にLVMHに合流して、ルイヴィトンと同じ棚で売られる。高級品は「誰が飲んだか」の歴史が、味を凌駕する。時間しか作れない堀の典型例。",
    otoraCommentEn: "Moët's strength is the history 'beloved by Napoleon' itself. Claude Moët founded the house in 1743; every time Napoleon stopped in Épernay, he bought champagne by the barrel and took it to the battlefield. An emperor's endorsement has worked for 283 years. With identical taste, 'Napoleon drank this' doubles the price. They joined LVMH in 1987 and now sit on the same shelf as Louis Vuitton. For luxury goods, the history of 'who drank it' overwhelms the taste. A textbook moat that only time can build.",
