    survivalKeyEn: "AWS's 30%+ operating margin backfills thin retail margins, creating a layered structure where one unit's losses are absorbed by another's. They can keep walking into high-margin markets with 'your margin is my opportunity' precisely because a high-yield engine is always spinning somewhere in the portfolio. A financial design that makes 'losses are fine, reinvest' permanent.",
