    otoraCommentEn: "Amazon's operating philosophy is 'Your margin is my opportunity' — systematically destroy every market where competitors enjoy high margins. Bezos's madness: expanding from books → everything → AWS → advertising → healthcare while reinvesting under a 'losses are fine' doctrine for 20-plus years. AWS's 30%+ operating margin supports the thin retail margins, and 1 million logistics robots chase efficiency to its limit. As long as the 16 Leadership Principles function as culture, 'Day 1' continues. Bezos knows better than anyone it ends the instant they bureaucratize.",
