    survivalKeyEn: "Codifying long-termism in the 1997 shareholder letter structurally deflected the dot-com crash's pressure to fake short-term profits. Through the triple blow of Lehman's bankruptcy warning, Pets.com's collapse, and a 94% stock drop, posting a first profitable quarter ($5M) in Q4 2001 earned the right to keep reinvesting — which is what made the AWS launch (2006) possible five years later.",
