    situation: "豊田喜一郎が父・佐吉の豊田自動織機自動車部から1937年8月28日にトヨタ自動車工業として独立。1936年発売のAA型乗用車はChrysler Airflow参考の模倣設計で、品質はFordに大きく劣後。同年成立の自動車製造事業法でFord・GMの輸入が排除され国産優遇が始まったが、日中戦争開戦で原材料統制が強まり、戦時下の軍用トラックG1/KC型生産にシフトせざるを得なかった。挙母工場建設で資金は逼迫、織機事業からの内部補填が命綱。",
    situationEn: "Kiichiro Toyoda spun the Automobile Department out of his father Sakichi's Toyoda Automatic Loom Works, incorporating Toyota Motor Co., Ltd. on August 28, 1937. The Model AA passenger car released in 1936 was a copy-based design borrowing from the Chrysler Airflow, with quality far below Ford's. The Automobile Manufacturing Industry Law of 1936 shut Ford and GM imports out and began protecting domestic makers, but with the outbreak of the Second Sino-Japanese War, raw-material rationing tightened and Toyota was forced to pivot to G1/KC military trucks. The Koromo Plant build strained cash; internal subsidies from the loom business were the lifeline.",
