    otoraComment: "ソフトバンクは「孫正義という個人のネットワークと交渉力」が全資産の会社。創業時に「豆腐を1丁2丁と数えるように1兆2兆と数える」と宣言した男が、Alibaba $20M→$60B+、ARM買収$32B、Vision Fund $100Bと毎回最大の賭けをし続けた。有利子負債$120B+のレバレッジ経営は諸刃の剣、WeWork失敗もあるが打率で補う。「AIは人類史上最大の革命」に全財産を賭ける覚悟——ワンマンリスクと表裏一体の300年ビジョン。",
