    otoraCommentEn: "Anthropic in 2021 scored NCG 38 — a research organization with zero product and zero users. The Amodei siblings led a group exit of seven-plus top researchers from OpenAI; the $124M Series A was led by individual angels (Jaan Tallinn, Moskovitz) betting on the slogan 'safe AI.' OpenAI had just turned toward GPT-3 commercialization, and FB / Google / MS all saw safety research as cost. At that exact moment, the contrarian articulation 'safety is the competitive advantage' — Insight=5 — was a prophecy written 18 months before the ChatGPT shock (November 2022). Constitutional AI was unpublished; Claude was unreleased. Yet Team=5 (GPT-3 co-author + Scaling Laws author + the leader of interpretability) + Timing=5 + Insight=5 — triple max — secured survival. Amazon's $8B in total came in 2023-24, and the $61.5B valuation in March 2025.",
