    otoraCommentEn: "The essence of Netflix 1997 is that it began with an experiment — mailing a DVD to themselves in a CD-sized envelope to see if it would survive. The name itself, Net + Flicks, was already in place at founding: physical rental was a stepping stone; streaming was the endgame, articulated in 1997. The same company that walked into Blockbuster's office in 2000 with a $50M acquisition offer and was laughed out the door went on to bury Blockbuster a decade later. At the time the moat was near zero, traction was zero, and the market was unripe. They won on founder insight (Insight = 5) and a direct hit on customer pain — flat-rate, no late fees.",
