    situationEn: "Shigenobu Nagamori started with three colleagues in a prefab hut in Kyoto. Specialized in precision motors and became the world's largest motor maker through 70+ acquisitions. The 'do it now, do it without fail, do it until it's done' spirit moved them from HDDs to appliances to automotive. Invested heavily in the EV drive motor 'E-Axle,' then announced a withdrawal from the business in May 2026.",
