      solution: "精密小型モーターを核に、トーソク、コパル、三協精機などへの資本参加で製品ラインを広げた",
      team: "永守重信と3人の同志が4人で創業した執念の会社。一方で後継社長は定着せず、2026年9月にも社長が辞任した",
      traction: "精密小型モーターで世界トップのシェア。2025年3月期の連結売上は約2兆6,078億円、従業員は約10万4,000人",
      moat: "1984年の米ファンメーカーの事業買収を皮切りに、2025年7月までに75社を買収。製品群と量産技術を積み上げた",
      revenue: "用途はHDD、自動車、家電、産業用と幅広い。2010年に米エマソンのモーター事業を買い、産業用を強めた",
      financial: "2025年3月期は連結売上約2兆6,078億円、純利益約1,607億円。買収で大きくした規模を利益につなげた",
