    otoraComment: "日本電産の凄みは永守重信の「すぐやる、必ずやる、出来るまでやる」の執念。1973年に社員4人、プレハブ小屋から始めた会社が、1984年の米国企業の事業買収を皮切りに2025年7月までに75社を買い、売上2.6兆円のモーター大手になった。「回るものは全てうちがやる」の一点突破で、HDD→家電→車載へ展開。EV駆動モーター「E-Axle」には大きく賭けたが、2026年5月に撤退方針が報じられた。さらに2025年に発覚した不適切会計では、第三者委員会が創業者による過度な業績プレッシャーを指摘している。執念は強さの源であり、同時に後継者問題という構造的リスクの根でもある——永守の執念を、誰がどう引き継ぐのか。",
    otoraCommentEn: "Nidec's awe is Shigenobu Nagamori's tenacity: 'do it now, do it without fail, do it until it's done.' A man who started with four people in a prefab hut built the world's largest motor maker through 70+ acquisitions. The 'Nagamori style' turnaround — making acquired companies profitable within a year — is something no one else can imitate. Breaking through on the single bet 'if it spins, we make it,' they expanded from HDD to appliances to automotive. It bet big on the E-Axle EV drive motor, then announced its withdrawal in 2026. The one structural risk is succession — who inherits Nagamori's tenacity?",
