    situation: "1912年、早川徳次が東京・本所で金属加工業を始めた。資本金50円、3人での出発で、同年にベルトのバックル「徳尾錠」を考案した。1915年に金属製の繰出鉛筆を発明し、これが「シャープペンシル」として社名の由来になる。1925年に国産初の鉱石ラジオを量産し、1964年に世界初のオールトランジスタ電卓、1973年に液晶表示の電卓を出した。液晶に賭けた同社は2004年に亀山工場、2009年に堺工場を稼働させたが、値崩れで巨額の赤字に陥り、2016年に台湾の鴻海の傘下に入った。",
    situationEn: "Founded in 1912 by Tokuji Hayakawa, starting with the mechanical pencil that gave the company its name. Led the world in calculators and LCD TVs. In the 2000s, the 'Kameyama model' dominated the LCD TV market, with a peak market cap over $30B. But right after pouring capital into LCD panel plants (Sakai, Kameyama), the global financial crisis hit and Korean and Chinese makers rose, sending LCD prices crashing. In 2016 the company was acquired by Taiwan's Foxconn for $3.8B — the first symbolic case of a Japanese electronics maker passing under foreign ownership.",
