    failReason: "「亀山液晶への過剰投資＋リーマンショック＋韓中台頭」の三重苦。技術者出身経営が「我々の液晶は最高品質」と信じすぎ、コモディティ化を見誤った。堺工場（$30億）と亀山工場（$20億）に巨額投資した直後にリーマンショック＋韓国Samsung・LG＋中国BOEの台頭で液晶価格が半分以下に。引き返せなくなった。鴻海買収後は黒字化したが、日本電機メーカー初の外資傘下となった象徴。",
    failReasonEn: "A triple blow of 'over-investment in Kameyama LCDs + the global financial crisis + the rise of Korea and China.' Engineering-driven management believed too strongly that 'our LCDs are top quality' and misread commoditization. Right after committing massive capital to the Sakai plant ($3B) and the Kameyama plant ($2B), the financial crisis hit and Korea's Samsung and LG plus China's BOE pushed LCD prices to less than half. There was no turning back. After the Foxconn acquisition, profitability returned, but the company remains the first symbolic case of a Japanese electronics maker passing under foreign ownership.",
    otoraComment: "シャープは「日本電機メーカー敗北の象徴」。2004年に亀山、2009年に堺と液晶工場へ巨額を投じ、2005年度には液晶テレビを年400万台売った。だが堺が動き出したのはリーマン・ショックの直後。韓中メーカーの台頭で液晶価格が崩れ、2013年3月期に5,453億円の最終赤字、2015年3月期には自己資本比率1.5%まで追い込まれた。引き返せなくなり、2016年に鴻海が3,888億円を出資して議決権の66%を握った。技術者経営の典型的な落とし穴——「我々の技術は最高だから守れる」とコモディティ化を見誤った。鴻海傘下では2018年3月期に4年ぶりの最終黒字に戻したが、2024年にはテレビ向け液晶の生産を止めた。「他社がまねする商品をつくれ」という創業者の言葉は、まねされた後の戦い方までは教えてくれなかったのかもしれない。",
    otoraCommentEn: "Sharp is 'the symbol of Japanese electronics defeat.' In the 2000s, the Kameyama model held over 20% global share in LCD TVs. But right after committing huge capital to the Sakai and Kameyama plants, the global financial crisis hit and Korea + China rose, sending LCD prices crashing. There was no turning back, and in 2016 it was acquired by Taiwan's Foxconn for $3.8B. A textbook engineer-led management trap — 'our technology is the best, so we can defend' meant misreading commoditization. Profitability returned under Foxconn, but the founder's bloodline passed into foreign hands.",
