    otoraCommentEn: "Toshiba is the symbol of 'a 150-year blue-chip on the brink of dismantlement.' A $1B accounting fraud in 2015 forced three CEO resignations, the Westinghouse nuclear business booked over $6B in losses, the semiconductor memory business was sold for $18B, and in 2023 the company was taken private via a JIP TOB — the retreat of one of Japan's oldest electronics names. Executive fraud + a dysfunctional board + cozy government ties pushed big-company disease to its limit. The moment 'too big to fail' became 'too rotten to save.' While Mitsui and Sumitomo have survived more than 300 years, Toshiba reached the edge of dismantlement in 150. A case that asks: what was different?",
