// スコア配分: 12項目(60) + 3軸(各10点×3=30) + ボーナス(0-10) = 100点満点
//
// 【BONUS_MAP 配点ガイドライン（4軸の総合判断）】
// Bonusは「12項目+3軸では定量化できない特別な偉業」への加点。以下4軸の総合評価:
//   ①時間軸: 長寿そのものの異常さ（金剛組1,447年、住友435年）
//   ②影響軸: 社会・文化・業界を変えた度合い（Apple デザイン、Netflix ストリーミング）
//   ③資本軸: 時価総額・経済的影響力（トヨタ、Microsoft）
//   ④戦略軸: 決定的意思決定・タイミング（Amazon AWS pivot、SpaceX 4回目成功）
//
// レンジ:
//   10: 4軸すべて突き抜け／文明レベル（Apple, トヨタ, 金剛組など選ばれし社）
//   8-9: 3軸で突き抜け（Netflix, Tesla, 住友, 任天堂）
//   6-7: 2軸で光る（Databricks, SpaceX, モエ）
//   4-5: 1軸で目立つ（Cloudflare, Kiva, サッポロ）
//   1-3: 教訓系（WeWork, Jawbone, TOMS）
//   0:   詐欺・空虚（Theranos, FTX, Pets.com）
//
