export function getBonus(c: CaseStudy, locale: string = "ja"): { value: number; reason: string } {
  const key = `${c.name}|${c.year}|${c.tier}`;
  const entry = BONUS_MAP[key];
  if (!entry) return { value: 0, reason: "" };
  const reason = locale === "en" && entry.reasonEn && entry.reasonEn.trim().length > 0 ? entry.reasonEn : entry.reason;
  return { value: entry.value, reason };
}

export function getCombinedScore(c: CaseStudy): number {
  const bonus = getBonus(c).value;
  return c.total + (c.axes.society + c.axes.customer + c.axes.self) * 2 + bonus;
}

// 存続ライン: 100点満点換算で47点（旧60点満点で28点の比例）
export const SURVIVAL_LINE = 47;
// 卓越ライン（アレテー）: 100点満点換算で75点（旧60点満点で45点の比例）
export const EXCELLENT_LINE = 75;

/** 創業年から現在までの年数。year が number or "1520s" 形式に対応。取れなければ null。 */
export function getCaseAge(c: CaseStudy, now: number = new Date().getFullYear()): number | null {
  const y = typeof c.year === "number" ? c.year : parseInt(String(c.year).match(/\d{3,4}/)?.[0] ?? "", 10);
  if (!Number.isFinite(y)) return null;
  return now - y;
}

/**
 * 創業年からの経過年に基づく「長寿レジェンド」バッジ。
 * bronze/silver/gold tier の企業では、tier バッジと冗長になるため null を返す。
 * 100年未満の企業も null。三井（tier: "japan", 352年）→ silver など。
 */
export type LegendBadgeTier = "bronze" | "silver" | "gold";
export function getAgeBadge(c: CaseStudy): LegendBadgeTier | null {
  // bronze/silver/gold は tier バッジと冗長になるため除外。
  // craft は「時のふるい」の文脈で長寿バッジを併用する（500年+/300年+/100年+を示す）。
  if (c.tier === "bronze" || c.tier === "silver" || c.tier === "gold") return null;
  const age = getCaseAge(c);
  if (age === null || age < 100) return null;
  if (age >= 500) return "gold";
  if (age >= 300) return "silver";
  return "bronze";
}

/**
 * フィルタキーに対するマッチング判定。
 * bronze/silver/gold は tier ではなく「創業年からの経過年」で判定するため、
 * tier: "japan" の老舗（三井 352年, 住友 435年 など）も 100年+/300年+ タブに正しく表示される。
 */
export function matchesFilter(filter: string, c: CaseStudy): boolean {
  if (filter === "all") return true;
  if (filter === "bronze" || filter === "silver" || filter === "gold") {
    const age = getCaseAge(c);
    if (age === null) return false;
    if (filter === "bronze") return age >= 100 && age < 300;
    if (filter === "silver") return age >= 300 && age < 500;
    return age >= 500; // gold
  }
  if (filter === "longevity") {
    const age = getCaseAge(c);
    return age !== null && age >= 100;
  }
  return c.tier === filter;
}

/**
 * 一覧表示用にケーススタディを正規化する。
 * 同一 eraGroup を持つ複数エントリ（例: Apple 1976 god / Apple 1997 startup）は、
 * tier ランクが最も高いものを「正準」として残す（god > earth > craft > startup > fail 等）。
 * 同 tier なら最新年を選ぶ。eraGroup なしの entry はそのまま。
 *
 * これで "現在の達成期" が一覧に出て、"初期の苦闘期" は隠れる。
 * モーダル詳細では `getEraGroupCases(eraGroup)` で時系列の他エントリを取得する。
 */
export function getCanonicalCases(): CaseStudy[] {
  const yearOf = (c: CaseStudy): number => {
    const y = typeof c.year === "number" ? c.year : parseInt(String(c.year).match(/\d{3,4}/)?.[0] ?? "0", 10);
    return Number.isFinite(y) ? y : 0;
  };
  // tier ランク（数値が大きいほど "達成度高" = 一覧で優先表示）
  const tierRank: Record<CaseStudy["tier"], number> = {
    god: 100,
    earth: 90,
    craft: 80,
    gold: 70,
    silver: 60,
    bronze: 50,
    japan: 40,
    social: 35,
    startup: 30,
    fail: 10,
  };
  const rankOf = (c: CaseStudy): number => tierRank[c.tier] ?? 0;
  // eraGroup ごとに「tier ランク最大、同点なら最新年」の entry を選ぶ
  const canonicalByGroup = new Map<string, CaseStudy>();
  for (const c of CASE_STUDIES) {
    if (!c.eraGroup) continue;
    const cur = canonicalByGroup.get(c.eraGroup);
    if (!cur) {
      canonicalByGroup.set(c.eraGroup, c);
      continue;
    }
    const newRank = rankOf(c);
    const curRank = rankOf(cur);
    if (newRank > curRank || (newRank === curRank && yearOf(c) > yearOf(cur))) {
      canonicalByGroup.set(c.eraGroup, c);
    }
  }
  return CASE_STUDIES.filter((c) => {
    if (!c.eraGroup) return true;
    return canonicalByGroup.get(c.eraGroup) === c;
  });
}

/** 同一 eraGroup の全エントリを年昇順で返す（時系列タブ用）。*/
export function getEraGroupCases(eraGroup: string): CaseStudy[] {
  const yearOf = (c: CaseStudy): number => {
    const y = typeof c.year === "number" ? c.year : parseInt(String(c.year).match(/\d{3,4}/)?.[0] ?? "0", 10);
    return Number.isFinite(y) ? y : 0;
  };
  return CASE_STUDIES.filter((c) => c.eraGroup === eraGroup).sort((a, b) => yearOf(a) - yearOf(b));
}

/**
 * ASCII文字列からケーススタディのスラグを生成する。
 * nameEn を優先し、なければ name から英字・数字のみ抽出する。
 * OG画像エンドポイントや共有URLで利用する。
 *
 * 同一企業を複数時点で並べる場合（eraGroup 付き）は、年号サフィックスで一意化する。
 * 例: "spacex-2002", "spacex-2024"
 */
export function slugifyCase(c: CaseStudy): string {
  const src = (c.nameEn ?? c.name ?? "").toLowerCase();
  const base = src.replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "case";
  if (c.eraGroup) {
    const year = typeof c.year === "number" ? String(c.year) : String(c.year).match(/\d{3,4}/)?.[0] ?? "";
    if (year) return `${base}-${year}`;
  }
  return base;
}

/** スラグ文字列から該当ケースを引く。見つからなければ undefined。
 *
 * eraGroup 付きの社（Apple/Microsoft 等）は本来 `${name}-${year}` 形式だが、
 * 過去にシェアされた `apple` のような bare slug にも fallback する:
 * 同名の中で最も新しい canonical（startup tier 以外）を返す。これで外部に出回った
 * 古いリンクが死なない。 */
export function findCaseBySlug(slug: string): CaseStudy | undefined {
  const target = slug.toLowerCase();
  // 1. 完全一致
  const exact = CASE_STUDIES.find((c) => slugifyCase(c) === target);
  if (exact) return exact;
  // 2. bare slug fallback: name のローマ字化が target と一致する最新の canonical を返す
  const baseMatches = CASE_STUDIES.filter((c) => {
    const src = (c.nameEn ?? c.name ?? "").toLowerCase();
    const base = src.replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
    return base === target;
  });
  if (baseMatches.length === 0) return undefined;
  // canonical（tier !== "startup"）優先、なければ最新 year
  const canonical = baseMatches.filter((c) => c.tier !== "startup");
  const pool = canonical.length > 0 ? canonical : baseMatches;
  return pool.sort((a, b) => Number(b.year) - Number(a.year))[0];
}